package ec.dmt.admin.school;
import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/api/inspector") public class InspectorAttendanceController { private final InspectorCourseRepository assignments; private final StudentRepository students; private final AttendanceEventRepository events; private final LocalTime lateAfter; public InspectorAttendanceController(InspectorCourseRepository a,StudentRepository s,AttendanceEventRepository e,@Value("${app.attendance.late-after:08:00}") String lateAfter){assignments=a;students=s;events=e;this.lateAfter=LocalTime.parse(lateAfter);}
 @GetMapping("/attendance") public Summary attendance(org.springframework.security.core.Authentication auth,@RequestParam(required=false) LocalDate date){LocalDate day=date==null?LocalDate.now():date; Set<Long> courseIds=assignments.findByUserUsername(auth.getName()).stream().map(x->x.getCourse().getId()).collect(Collectors.toSet()); List<Student> assigned=students.findAll().stream().filter(s->courseIds.contains(s.getParallel().getCourse().getId())&&s.isActive()).toList(); Map<String,AttendanceEvent> marks=events.findByEventTimeBetween(day.atStartOfDay(ZoneId.systemDefault()).toInstant(),day.plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant()).stream().collect(Collectors.toMap(AttendanceEvent::getBiometricUserId,x->x,(a,b)->a)); List<Row> rows=assigned.stream().map(s->{AttendanceEvent e=marks.get(s.getBiometricUserId());String state=e==null?"ABSENT":e.getEventTime().atZone(ZoneId.systemDefault()).toLocalTime().isAfter(lateAfter)?"LATE":"PRESENT";return new Row(s.getId(),s.getBiometricUserId(),s.getFirstName(),s.getLastName(),s.getParallel().getCourse().getName(),s.getParallel().getName(),state,e==null?null:e.getEventTime());}).toList();return new Summary(day,rows.stream().filter(x->x.state().equals("PRESENT")).count(),rows.stream().filter(x->x.state().equals("LATE")).count(),rows.stream().filter(x->x.state().equals("ABSENT")).count(),rows);}
 public record Summary(LocalDate date,long present,long late,long absent,List<Row> students){} public record Row(Long id,String biometricUserId,String firstName,String lastName,String course,String parallel,String state,Instant arrival){} }
